import React from "react";
import '../css/login.css';
import { Link, useNavigate } from "react-router-dom";
import { FaPhoneAlt } from "react-icons/fa";

class Login extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            phone: '',
            error: ''
        };
        this.phoneRef = React.createRef();
    }

    handleSubmit = (e) => {
        e.preventDefault();
        const phone = this.phoneRef.current.value.trim();
        
        // حذف کاراکترهای غیرعددی (مثل فاصله، خط تیره و ...)
        const cleanPhone = phone.replace(/\D/g, '');
        
        if (cleanPhone.length === 11) {
            // شماره معتبر است
            this.setState({ error: '' });
            alert('شماره موبایل با موفقیت ثبت شد!');
            // اقدام بعدی مثل ارسال کد تایید
        } else {
            // شماره نامعتبر
            this.setState({ 
                error: 'شماره موبایل باید ۱۱ رقم باشد' 
            });
            this.phoneRef.current.focus();
        }
    };

    render() {
        const { error } = this.state;
        
        return (
            <main className="container mt-4 pt-5">
                <img src="../img/aaa.png" alt="fixed logo" className="fixed-top-left" />
                <div className="align-items-center position-fixed top-50 start-50 translate-middle">
                    <div className="login-box-login shadow text-center item-back boder p-4 rounded-5 d-flex justify-content-center align-items-center">
                        <div className="welcome-box">
                            <img src="../img/aaa.png" alt="logo" />
                            <div className="mt-5">
                                <form className="mt-4" onSubmit={this.handleSubmit}>
                                    <div className="custom-floating">
                                        <FaPhoneAlt className="custom-icon" />
                                        <input
                                            type="tel"
                                            id="phone"
                                            className={`custom-input ${this.state.error ? 'is-invalid' : ''}`}
                                            placeholder=" "
                                            dir="rtl"
                                            ref={this.phoneRef}
                                            onChange={(e) => {
                                                this.setState({ phone: e.target.value });
                                                if (this.state.error) this.setState({ error: '' });
                                            }}
                                        />
                                        <label htmlFor="phone" className="custom-label">شماره موبایل</label>
                                    </div>
                                    {error && (
                                        <div className="text-danger text-end small">
                                            {error}
                                        </div>
                                    )}
                                    <button type="submit" className="custom-btn">
                                        ارسال کد
                                    </button>
                                </form>
                            </div>
                        </div>
                    </div>
                </div>
            </main>
        );
    }
}

export default Login;
